-- ViteHub Agent invocation journal for the Console. Generated by d1AgentInvocationSchema().
-- pnpm exec wrangler d1 execute email-labeller --remote --file scripts/agent-invocations.sql
CREATE TABLE IF NOT EXISTS vitehub_agent_invocations (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL,
  agent_name TEXT NOT NULL,
  search TEXT NOT NULL,
  summary TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  record TEXT NOT NULL,
  revision INTEGER NOT NULL DEFAULT 0,
  claim_id TEXT,
  claim_token TEXT,
  claim_expires_at INTEGER
);
CREATE INDEX IF NOT EXISTS vitehub_agent_invocations_status_sequence ON vitehub_agent_invocations (status, sequence DESC);
CREATE INDEX IF NOT EXISTS vitehub_agent_invocations_status_updated_at ON vitehub_agent_invocations (status, updated_at);
CREATE INDEX IF NOT EXISTS vitehub_agent_invocations_agent_name_sequence ON vitehub_agent_invocations (agent_name, sequence DESC);
